    if (u.kind || !u.lecture) continue;
    let add = MORE[id];
    if (!add && u.subject === 'kanken') { const nm = plainName(u.name), hit = KK.find(([re]) => re.test(nm)); if (hit) add = hit[0].source === '読み' ? [hit[1][0] + KFIG, ...hit[1].slice(1)] : hit[1]; }
